INSERT INTO `cw_archetypes_locale` (`archetype_id`, `locale`, `name`, `description`) VALUES
(1, 'ruRU', 'Клинок пепла', 'Воин и маг в одном клинке: огненные удары и рассечения, огненные шары между атаками и сигнальный костёр на поле боя.'),
(2, 'ruRU', 'Ледопламенный дуэлянт', 'Разбойник и маг: в одной руке огонь, в другой — лёд. Обжигающие и замораживающие удары, а «Взрыв противоположностей» соединяет обе стихии.'),
(3, 'ruRU', 'Пепельный жнец', 'Воин и чернокнижник, владеющие огнём и тьмой: обжигающие и теневые удары, проклятия и «Ожог души», а огненная турель удерживает позицию.'),
(4, 'ruRU', 'Несущий чуму', 'Разбойник и чернокнижник, сочетающие яд и тьму: отравленные и затенённые клинки, порча и агония, а у ног крадётся жук.'),
(5, 'ruRU', 'Странник рассвета', 'Охотник и паладин, озарённые Светом и тайной магией: освящённые и магические выстрелы, печати и правосудие для ближнего боя.'),
(6, 'ruRU', 'Коготь Бездны', 'Друид и жрец, повелевающие тьмой: кошачьи когти и полосующие удары несут силу Бездны, перед прыжком звучат слова Тьмы, а добить врага помогает Исчадие Тьмы.'),
(7, 'ruRU', 'Сумеречный рыцарь', 'Воин и жрец на границе Света и тьмы: священные и теневые удары, щит веры и взрывы разума вблизи.'),
(8, 'ruRU', 'Чародейский стрелок', 'Охотник и маг владеют тайной магией и льдом: чародейские и ледяные стрелы, скачок из опасности и ледяные копья, пока ловушка держит врага.'),
(9, 'ruRU', 'Неудержимый воин', 'Друид и воин владеют землёй: могучий медведь наносит увечья и калечит, а крики и громовые удары воина не дают врагам отступить.'),
(10, 'ruRU', 'Громовой крестоносец', 'Паладин и шаман соединяют Свет и бурю: печати и правосудие дополняются Оружием неистовства ветра, шоками, освящением и тотемами.'),
(11, 'ruRU', 'Зимний следопыт', 'Охотник и шаман владеют льдом: ледяные выстрелы и ловушки, Оружие ледяного клейма и цепная молния; Тотем оков земли не даёт добыче уйти.'),
(12, 'ruRU', 'Ядовитый ловчий', 'Друид и разбойник сочетают яд и землю: кошачьи когти отравлены, яды разбойника усиливают каждый полосующий удар, а земные удары ломают броню.'),
(13, 'ruRU', 'Инквизитор', 'Паладин и разбойник служат Свету: освящённые коварные удары и внезапные атаки, печать за каждым ударом и божественный щит для спасения.'),
(14, 'ruRU', 'Звёздный мудрец', 'Друид и маг владеют тайной магией и огнём: лунный огонь и звёздный огонь, огненные шары и огненный столб; если этого мало — взрыв противоположностей.'),
(15, 'ruRU', 'Вестник могил', 'Жрец и чернокнижник повелевают тьмой и чумой: щиты и исцеление для союзников, чума, порча и истощение для остальных.'),
(16, 'ruRU', 'Повелитель зверей', 'Охотник и чернокнижник никогда не остаются одни: приручённый зверь, демон, ядовитый жук и турель, а сверху — огненные и теневые стрелы.'),
(17, 'ruRU', 'Огненный безумец', 'Маг и чернокнижник согласны лишь в одном: всё должно гореть. Огненные шары, жертвенный огонь, адское пламя, дождь огня и сигнальный костёр для финала.'),
(18, 'ruRU', 'Плут', 'Разбойник и жрец умеют выкрутиться словами: успокоить противника, обчистить его карманы и подчинить разум; если не выйдет — ударить из тени.'),
(19, 'ruRU', 'Меняющий облик', 'Друид и шаман не задерживаются в одном облике: по очереди волк, медведь и кошка, земные и ледяные удары, а между превращениями — исцеляющие волны.'),
(20, 'ruRU', 'Мастер на все руки', 'Знаковые способности всех классов, объединённые способностями героя: «Мастер на все руки», «Репертуар» и «Всплеск случайного пути».');
